enum ActionRisk { readOnly, reversible, externalCommunication, financial, destructive }
enum ActionDisposition { suggestOnly, approvalRequired, deny }
class ActionRequest { const ActionRequest({required this.id,required this.risk,required this.userInitiated,required this.validPayload,this.approved=false}); final String id; final ActionRisk risk; final bool userInitiated,validPayload,approved; }
class ActionPolicyResult { const ActionPolicyResult(this.disposition,this.reason); final ActionDisposition disposition; final String reason; }
class ActionApprovalPolicy { const ActionApprovalPolicy(); ActionPolicyResult evaluate(ActionRequest a) { if(a.id.trim().isEmpty||a.id!=a.id.trim()||!a.validPayload)return const ActionPolicyResult(ActionDisposition.deny,'Invalid action or payload'); if(!a.userInitiated)return const ActionPolicyResult(ActionDisposition.suggestOnly,'Not user initiated'); if(a.risk==ActionRisk.readOnly)return const ActionPolicyResult(ActionDisposition.suggestOnly,'Read-only suggestion'); if(a.risk==ActionRisk.destructive&&!a.approved)return const ActionPolicyResult(ActionDisposition.deny,'Destructive action requires approval'); if((a.risk==ActionRisk.externalCommunication||a.risk==ActionRisk.financial)&&!a.approved)return const ActionPolicyResult(ActionDisposition.approvalRequired,'Human approval required'); return const ActionPolicyResult(ActionDisposition.suggestOnly,'Proposal only; backend authorization still required'); } }
